css:
.avatar {
  position: relative;
  display: grid;
  place-items: center;
  width: 64px;
  height: 64px;
  margin: 32px;
  border-radius: 12px;
  background: #3f3f46;
}

.badge {
  position: absolute;
  top: -6px;
  right: -6px;
  min-width: 22px;
  padding: 2px 6px;
  border-radius: 999px;
  background: #f97316;
  color: #fff;
  font-size: 12px;
  text-align: center;
}
